          introduction: 'Raw print output is fine for debugging, but users expect tidy sentences and rounded numbers. This lesson shows how f-strings embed values inside text and format numbers to a chosen precision.',
          concept: 'An f-string starts with the letter f before the opening quote, and any expression inside curly braces is evaluated and inserted, for example f\'{name} is {age} years old\'. You can format numbers inside the braces with a format spec, such as f\'{price:.2f}\' to show exactly two decimal places. F-strings can also contain arithmetic, like f\'{a + b}\', and method calls, like f\'{name.upper()}\'. Older approaches still work: the format() method and plain concatenation with +, but f-strings are shorter, faster, and easier to read. Remember that the braces belong to the f-string, so literal braces need doubling as {{ and }}. A common slip here: Forgetting the f before the quote, so {name} prints literally instead of the value. The debugging exercise below demonstrates it: Without a format spec the float prints as 13.5. Adding :.2f inside the braces forces exactly two decimal places.',
          syntax: 'name = \'Ada\'\nprice = 19.99\nprint(f\'{name} paid ${price:.2f}\')',
          analogy: 'An f-string is like a form letter with blanks: you write the sentence once, and Python fills in each blank with the current value.',
          exampleCode: 'item = \'coffee\'\nprice = 4.5\nquantity = 3\ntotal = price * quantity\nprint(f\'{quantity} x {item} = ${total:.2f}\')',
