          concept: 'Python provides + for addition, - for subtraction, * for multiplication, and ** for powers, so 2 ** 3 is 8. Division has two forms: / always gives a float, for example 7 / 2 is 3.5, while // is floor division and gives the whole part, so 7 // 2 is 3. The % operator gives the remainder, so 7 % 2 is 1, which is handy for checking evenness or wrapping values. Python follows the usual precedence: parentheses first, then **, then * / // %, then + and -. You can also use augmented assignment such as total += 5 as a shortcut for total = total + 5. A common slip here: Expecting / to give a whole number when it always returns a float. The debugging exercise below demonstrates it: The code used floor division // instead of the remainder operator %. Changing it to % gives 1.',
