          concept: 'Comparison operators return a bool: == tests equality, != tests inequality, and <, >, <=, >= test ordering, so 5 > 3 is True. A single = assigns a value while == compares, and mixing them up is one of the most common beginner errors. Logical operators combine booleans: and is True only when both sides are True, or is True when at least one side is True, and not flips a value. Python lets you chain comparisons naturally, so 1 < x < 10 checks both bounds at once. Comparisons also work on strings, which compare alphabetically, so \'apple\' < \'banana\' is True. A common slip here: Using = instead of == inside a comparison, which assigns instead of testing. The debugging exercise below demonstrates it: Using or makes the test pass when either half is true, and 90 >= 18 is true. Using and requires both halves, so 90 correctly fails.',
