          introduction: 'Some decisions have two layers: first check the broad case, then refine it. This lesson covers nested if statements for layered logic and the one-line ternary expression for simple either/or choices.',
          concept: 'A nested if is an if statement placed inside the block of another if, so the inner test only runs when the outer test passed. This is useful for layered rules such as \'if the user is logged in, then check whether they are an admin\'. Deep nesting quickly becomes hard to read, so flattening with and or returning early is often better. The ternary expression has the form value_if_true if condition else value_if_false, for example \'Adult\' if age >= 18 else \'Minor\'. Ternaries are best for short, simple choices; stuffing complex logic into one line makes code harder to understand. Both forms produce the same result when used well, so choose the clearer one. A common slip here: Nesting so deeply that the logic is hard to follow instead of combining conditions with and. The debugging exercise below demonstrates it: The two result values were swapped. The value before if is used when the condition is True, so \'Adult\' must come first.',
          syntax: 'age = 20\nstatus = \'Adult\' if age >= 18 else \'Minor\'',
          analogy: 'Nested conditions are like a building with a locked lobby and locked offices: you only reach the inner door if the outer one let you in.',
          exampleCode: 'age = 20\nhas_ticket = True\nif age >= 18:\n    if has_ticket:\n        print(\'Welcome in!\')\n    else:\n        print(\'You need a ticket.\')\nelse:\n    print(\'You must be 18 or older.\')',
