          introduction: 'Some tasks repeat an unknown number of times, such as asking for input until it is valid. This lesson covers while loops, which repeat while a condition stays true, and the break and continue statements that control them.',
          concept: 'A while loop checks its condition before every pass and runs the block only while the condition is True, so while count < 5: repeats five times if count increases each pass. The danger is an infinite loop: if nothing inside the body changes the condition, the loop never ends and the program hangs. The break statement exits the loop immediately, which is handy for \'stop when you find it\' searches. The continue statement skips the rest of the current pass and jumps to the next condition check. Use for loops when you know how many times to repeat, and while loops when the stopping point depends on data that arrives during the loop. A common slip here: Forgetting to update the variable in the condition, creating an infinite loop. The debugging exercise below demonstrates it: Nothing inside the loop changes count, so the condition count > 0 stays True forever. Decrementing count each pass lets the loop finish.',
