          concept: 'A dictionary is written with curly braces and colons, for example ages = {\'Ada\': 30, \'Liam\': 25}, and you read a value with ages[\'Ada\']. Adding or updating an entry is the same assignment, ages[\'Mia\'] = 28, and ages.get(\'Noor\', 0) returns a default instead of raising KeyError for a missing key. The keys(), values(), and items() methods let you loop over a dictionary, and del ages[\'Liam\'] removes an entry. A set is written with curly braces but no colons, for example {1, 2, 3}, and it automatically drops duplicates; sets support add(), remove(), and maths-like operations such as union with | and intersection with &. Dictionaries are for lookups by name, sets are for membership and uniqueness. A common slip here: Accessing a missing key directly, which raises KeyError instead of using .get() with a default. The debugging exercise below demonstrates it: Direct indexing raises KeyError for missing keys. Using .get() with a default returns the fallback value instead.',
          syntax: 'ages = {\'Ada\': 30, \'Liam\': 25}\nprint(ages[\'Ada\'])\nages[\'Mia\'] = 28\nprint(ages.get(\'Noor\', \'unknown\'))',
          analogy: 'A dictionary is like a phone book: you look up a name and get a number. A set is like a bag of marbles where duplicates simply cannot exist.',
          exampleCode: 'scores = {\'Ada\': 88, \'Liam\': 92}\nscores[\'Mia\'] = 95\nprint(\'Ada scored\', scores[\'Ada\'])\nfor name, score in scores.items():\n    print(name, \'->\', score)\nprint(\'Unique letters in hello:\', len(set(\'hello\')))',
