          concept: 'Arguments can be passed positionally, in the order the parameters are defined, or by keyword, as in greet(name=\'Ada\', excited=True), which is clearer for functions with many parameters. A parameter can have a default value, for example def greet(name=\'friend\'):, and callers may omit it. Variables created inside a function are local: they exist only while the function runs and cannot be seen outside it. Variables defined at the top level are global and readable inside functions, but assigning to a global inside a function creates a new local unless you declare global. A good rule is to pass data in as arguments and return results, instead of reaching for globals. A common slip here: Passing arguments in the wrong order when calling positionally. The debugging exercise below demonstrates it: Assigning to total inside the function created a local variable, leaving the global untouched. Declaring global total makes the assignment affect the global.',
