          concept: 'The program reads two numbers and an operator such as +, -, *, or /, then uses an if/elif chain to pick the matching arithmetic operation. Keeping the calculation in a small function such as calculate(a, b, op) makes the code testable and reusable. Division needs a guard: if b is zero, print a friendly error instead of letting Python raise ZeroDivisionError. A while loop can keep the calculator running until the user types \'quit\', turning a one-shot script into a real tool. Input validation with try/except around int() or float() conversions prevents crashes when the user types letters. A common slip here: Forgetting to guard division by zero, which raises ZeroDivisionError. The debugging exercise below demonstrates it: The original divides without checking b. Adding a zero check returns a friendly error message instead of crashing.',
          syntax: 'def calculate(a, b, op):\n    if op == \'+\':\n        return a + b\n    if op == \'-\':\n        return a - b',
          analogy: 'A calculator is like a vending machine: you feed in two numbers and press an operator button, and the machine dispenses the answer.',
          exampleCode: 'def calculate(a, b, op):\n    if op == \'+\':\n        return a + b\n    if op == \'-\':\n        return a - b\n    if op == \'*\':\n        return a * b\n    if op == \'/\':\n        return a / b if b != 0 else \'Error: division by zero\'\nprint(calculate(10, 2, \'+\'))\nprint(calculate(10, 0, \'/\'))',
