          concept: 'The import statement loads a module by name, as in import math, after which you call its functions with the module prefix, math.sqrt(16). The form from math import sqrt lets you call sqrt(16) directly, and import math as m gives the module a shorter alias. The standard library includes math for numbers, random for randomness, datetime for dates and times, os for the operating system, json for data, and many more. Importing the same module twice is harmless because Python caches it, and imports conventionally sit at the top of the file. Wildcard imports with * are discouraged because they hide where names came from. A common slip here: Calling a function without importing its module, which raises NameError. The debugging exercise below demonstrates it: The math module was used without being imported. Adding import math at the top makes math.sqrt available.',
          syntax: 'import math\nprint(math.sqrt(16))\nprint(math.pi)\nfrom random import randint\nprint(randint(1, 10))',
          analogy: 'A module is like a toolbox in a shared workshop: you borrow the whole box (import math) or just the one wrench you need (from math import sqrt).',
          exampleCode: 'import math\nimport datetime\nprint(\'Square root of 25:\', math.sqrt(25))\nprint(\'Pi:\', math.pi)\nprint(\'Today:\', datetime.date.today())\nprint(\'Floor of 3.7:\', math.floor(3.7))',
