          concept: 'The open() function opens a file in a mode: \'r\' for reading, \'w\' for writing (which erases existing content), and \'a\' for appending. The with statement, as in with open(\'notes.txt\', \'w\') as f:, closes the file automatically even if an error occurs. Reading options include f.read() for the whole content, f.readline() for one line, and f.readlines() for a list of lines, or simply looping over the file object. Writing uses f.write(text), and you must add \'\\n\' yourself because write does not add newlines. Trying to open a missing file for reading raises FileNotFoundError, so check existence or handle the error. Always specify encoding=\'utf-8\' for text files to handle non-English characters correctly. A common slip here: Opening a file in \'w\' mode when you meant to append, erasing the existing content. The debugging exercise below demonstrates it: The file was never closed, so the buffered write may never reach disk. Using with closes the file and flushes the write.',
          syntax: 'with open(\'notes.txt\', \'w\', encoding=\'utf-8\') as f:\n    f.write(\'Hello, file!\\n\')\nwith open(\'notes.txt\', encoding=\'utf-8\') as f:\n    print(f.read())',
          analogy: 'A file is like a notebook: opening it in write mode gives you a blank page, append mode lets you add to the end, and the with statement is closing the notebook when you finish.',
