          concept: 'The csv module reads rows as lists with csv.reader, or as dictionaries with csv.DictReader when the file has a header row. Writing uses csv.writer, and newline=\'\' must be passed to open() on Windows to avoid blank rows. The json module converts between Python values and JSON text: json.loads(text) parses a JSON string into a dict or list, and json.dumps(value) converts a Python value back into a JSON string. JSON supports objects, arrays, strings, numbers, booleans, and null, which maps to Python\'s None. Choose CSV for flat, spreadsheet-like tables and JSON for nested or hierarchical data. Always wrap file parsing in error handling, because real-world files are often malformed. A common slip here: Opening a CSV file for writing without newline=\'\', which creates blank rows on Windows. The debugging exercise below demonstrates it: json.loads expects a JSON string, not a Python dict. Passing the string form, with double quotes, parses correctly.',
