          introduction: 'Inheritance lets a new class reuse and specialise an existing one. This lesson shows how subclasses inherit attributes and methods, override behaviour, and call back to the parent with super().',
          concept: 'A subclass is declared with the parent in parentheses, as in class Dog(Animal):, and it automatically inherits the parent\'s attributes and methods. A subclass can override a method by defining the same name, so Dog.speak() can return \'Woof!\' while Animal.speak() returns a generic sound. The super() function calls the parent version, which is how a subclass extends __init__ without duplicating it: super().__init__(name) runs the parent\'s setup first. Polymorphism means code can treat different subclasses uniformly, for example looping over animals and calling speak() on each to hear each animal\'s own sound. Inheritance models \'is a\' relationships, such as a Dog is an Animal, and should not be used just to share code. A common slip here: Forgetting to call super().__init__() in a subclass __init__, leaving parent attributes unset. The debugging exercise below demonstrates it: The subclass __init__ replaced the parent\'s without calling it, so self.name was never set. Calling super().__init__(name) runs the parent setup.',
          syntax: 'class Animal:\n    def speak(self):\n        return \'...\'\nclass Dog(Animal):\n    def speak(self):\n        return \'Woof!\'',
          analogy: 'Inheritance is like a family recipe book: children inherit the family recipes, but each child may tweak one recipe to make it their own.',
          exampleCode: 'class Animal:\n    def __init__(self, name):\n        self.name = name\n    def speak(self):\n        return \'...\'\nclass Dog(Animal):\n    def speak(self):\n        return \'Woof!\'\nclass Cat(Animal):\n    def speak(self):\n        return \'Meow!\'\nfor pet in [Dog(\'Rex\'), Cat(\'Mia\')]:\n    print(pet.name, \'says\', pet.speak())',
