              starterCode: 'n = int(input())\nsquares = [i * i for i in range(1, n + 1)]\nit = iter(squares)\n# print each square using next()\n',
              solution: 'n = int(input())\nsquares = [i * i for i in range(1, n + 1)]\nit = iter(squares)\nfor _ in range(n):\n    print(next(it))',
