          introduction: 'Comprehensions build a new collection from an old one in a single readable line. This lesson covers list and dict comprehensions, including conditions that filter as you build.',
          concept: 'A list comprehension has the form [expression for item in iterable], for example [x * x for x in range(5)] gives [0, 1, 4, 9, 16]. Adding an if clause filters items, so [x for x in range(10) if x % 2 == 0] keeps only the even numbers. A dict comprehension uses curly braces and a colon, such as {name: len(name) for name in names}, building a mapping in one line. Comprehensions are usually faster and clearer than an equivalent loop with append, but they should stay simple: if the logic needs several statements, a normal loop is more readable. You can nest comprehensions, but deeply nested ones are hard to read and best avoided. A common slip here: Writing a comprehension so long that nobody can read it, instead of using a loop. The debugging exercise below demonstrates it: The original has no filter condition. Adding if x % 2 == 0 after the for clause keeps only the even numbers.',
          syntax: 'squares = [x * x for x in range(5)]\nevens = [x for x in range(10) if x % 2 == 0]\nlengths = {w: len(w) for w in [\'apple\', \'kiwi\']}',
          analogy: 'A comprehension is like a recipe that says \'for each apple in the basket, peel it and put it in the bowl\' in one sentence instead of a whole page of steps.',
          exampleCode: 'squares = [x * x for x in range(1, 6)]\nevens = [x for x in range(10) if x % 2 == 0]\nlengths = {w: len(w) for w in [\'apple\', \'kiwi\', \'fig\']}\nprint(\'Squares:\', squares)\nprint(\'Evens:\', evens)\nprint(\'Lengths:\', lengths)',
