          concept: 'The app keeps tasks in a list of dictionaries, each with a title and a done flag, for example {\'title\': \'Buy milk\', \'done\': False}. A main loop reads a command, then dispatches to a function: add_task appends a new dict, list_tasks prints each task with a checkbox, and complete_task flips a task\'s done flag. Commands are parsed by splitting the input line into words, so \'add Buy milk\' becomes the command \'add\' plus the title \'Buy milk\'. Keeping each command in its own function makes the program easy to extend with new commands such as delete or save. Invalid commands print a help message instead of crashing. A common slip here: Storing tasks as plain strings, which makes tracking done/undone state awkward. The debugging exercise below demonstrates it: The code used ==, which compares, instead of =, which assigns. Assigning True updates the flag.',
