          exampleCode: 'tasks = []\ndef add_task(title):\n    tasks.append({\'title\': title, \'done\': False})\ndef list_tasks():\n    for i, t in enumerate(tasks, 1):\n        mark = \'x\' if t[\'done\'] else \' \'\n        print(f\'{i}. [{mark}] {t["title"]}\')\nadd_task(\'Buy milk\')\nadd_task(\'Read chapter 3\')\ntasks[0][\'done\'] = True\nlist_tasks()',
