                  content: 'Solution:\nfrom contextlib import contextmanager\n@contextmanager\ndef open_write(path):\n    f = open(path, \'w\', encoding=\'utf-8\')\n    try:\n        yield f\n    finally:\n        f.close()\n\nword = input()\nwith open_write(\'/tmp/cm.txt\') as f:\n    f.write(word)\nwith open(\'/tmp/cm.txt\', encoding=\'utf-8\') as f:\n    print(f.read())\nThe context manager opens the file, yields it for writing, and closes it in a finally block; the program then reads the file back.',
