          id: 'python-m23-l1',
          slug: 'python-m23-l1',
          title: 'Profiling and Big-O Thinking',
          objectives: [
            'Describe an algorithm\'s cost with Big-O notation',
            'Profile code with cProfile and timeit',
            'Replace a quadratic algorithm with a linear one',
          ],
          introduction: 'Fast code starts with knowing where time goes. This lesson introduces Big-O notation for reasoning about growth, and the profiling tools that show which lines actually cost the most.',
          concept: 'Big-O notation describes how an algorithm\'s work grows as the input grows: O(1) is constant, O(n) grows linearly, and O(n squared) explodes, so doubling the input quadruples the work. A loop inside a loop is often O(n squared), and replacing a list membership test with a set lookup can turn an O(n) scan into O(1). The timeit module times small snippets accurately, while cProfile profiles a whole program and reports how many times each function ran and how long it took. Always measure before optimising: intuition about bottlenecks is frequently wrong, and the profiler tells you the truth. The fastest code is often the simplest change, such as using a set for lookups or a formula instead of a loop.',
          syntax: 'import timeit\nprint(timeit.timeit(\'sum(range(100))\', number=1000))\nprint(timeit.timeit(\'[x*x for x in range(100)]\', number=1000))',
          analogy: 'Big-O is like judging a recipe by how it scales: a recipe that takes twice as long for twice as many guests is fine, but one that takes four times as long will ruin a big dinner.',
          exampleCode: 'import timeit\nlist_time = timeit.timeit(\'[x in [1,2,3] for x in range(100)]\', number=1000)\nset_time = timeit.timeit(\'[x in {1,2,3} for x in range(100)]\', number=1000)\nprint(\'List lookup:\', list_time)\nprint(\'Set lookup:\', set_time)',
          exampleLanguage: 'python',
          walkthrough: [
            'timeit runs each snippet 1000 times and reports the total.',
            'List membership scans the list each time.',
            'Set membership uses a hash lookup.',
            'The set version is typically faster even for tiny collections.',
            'Measuring beats guessing when you optimise.',
          ],
          commonMistakes: [
            'Optimising code before measuring, and speeding up a part that barely matters.',
            'Assuming a clever one-liner is faster than a simple loop without timing it.',
            'Forgetting that Big-O ignores constant factors, which matter for small inputs.',
          ],
          debuggingExercise: {
            prompt: 'This membership test is slow for large lists. How do you speed it up?',
            buggyCode: 'allowed = [1, 2, 3, 4, 5]\nprint(999999 in allowed)',
            fixedCode: 'allowed = {1, 2, 3, 4, 5}\nprint(999999 in allowed)',
            explanation: 'List membership scans every item, which is O(n). A set uses hashing, so membership is O(1) on average.',
          },
          miniChallenge: 'Write a program that reads n and prints the sum 1..n using the O(1) formula n*(n+1)//2 instead of a loop.',
          summary: 'Big-O describes how work grows with input size; profile with timeit and cProfile before optimising, and prefer sets for membership tests.',
