          introduction: 'Most programs talk to the internet through HTTP APIs that return JSON. This lesson shows how to make requests, read status codes, and parse the JSON that comes back.',
          concept: 'An HTTP request has a method such as GET or POST, a URL, headers, and an optional body, and the server answers with a status code and a body. A 200 means success, 404 means not found, and 500 means the server failed. Python\'s urllib.request.urlopen can fetch a URL, but the third-party requests library is simpler and more popular for real work. APIs usually return JSON, which you parse with json.loads into dicts and lists, then read the fields you need. Always check the status code before parsing, set a timeout so a dead server cannot hang your program, and handle errors with try/except around the request. Never hard-code API keys in source code; read them from environment variables instead.',
          syntax: 'import json\ntext = \'{"login": "octocat", "public_repos": 8}\'\ndata = json.loads(text)\nprint(data[\'login\'], \'has\', data[\'public_repos\'], \'public repos\')',
          analogy: 'An HTTP API is like a restaurant menu: you order (GET) a dish by name, the kitchen returns a plate (JSON), and the status code tells you whether the order succeeded.',
          exampleCode: 'import json\nresponse_text = \'{"login": "octocat", "public_repos": 8, "followers": 120}\'\ndata = json.loads(response_text)\nprint(\'User:\', data[\'login\'])\nprint(\'Public repos:\', data[\'public_repos\'])\nprint(\'Followers:\', data[\'followers\'])',
