          concept: 'A SELECT query reads rows: SELECT name FROM users WHERE age >= 18 ORDER BY name LIMIT 10 returns the names of adult users, sorted, at most ten. WHERE filters rows, ORDER BY sorts them, and LIMIT caps the count; aggregates such as COUNT(*) and AVG(age) summarise a column. Parameters are passed separately from the SQL text using ? placeholders, as in conn.execute(\'SELECT * FROM users WHERE name = ?\', (name,)), so the database treats the value as data, never as code. Building SQL with f-strings or concatenation lets a malicious input such as \' OR \'1\'=\'1 change the query\'s meaning, which is SQL injection, and parameters close that hole completely. The same pattern applies to INSERT, UPDATE, and DELETE.',
