          concept: 'The shortener keeps a counter and encodes each new id in base62, the digits 0-9, lowercase a-z, and uppercase A-Z, so id 62 becomes \'10\' and large ids stay short. A dictionary maps each code to its original URL, and a second dictionary can map URLs back to codes so the same URL always gets the same code. Encoding works by repeatedly dividing by 62 and taking remainders, which is the same idea as converting a number to another base. Lookups are O(1) dictionary reads, and a missing code returns a clear \'not found\' result instead of crashing. In a real service the dictionaries would be a database table, and the counter would be atomic so two requests never get the same id.',
          syntax: 'CHARS = \'0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ\'\ndef encode(n):\n    if n == 0:\n        return \'0\'\n    out = \'\'\n    while n:\n        out = CHARS[n % 62] + out\n        n //= 62\n    return out',
