          introduction: 'A scraper fetches pages, extracts data, and stores it, and doing it concurrently makes it far faster. This lesson designs the pipeline and the rules that keep a scraper polite and legal.',
          concept: 'A scraper has three stages: fetch downloads a page over HTTP, parse extracts the fields you need, such as titles and links, and store saves the results to a file or database. Fetching is I/O-bound, so a ThreadPoolExecutor can download many pages at once while the network waits overlap. Parsing HTML is usually done with a library such as BeautifulSoup, which handles messy real-world markup better than regular expressions. A responsible scraper checks robots.txt, identifies itself with a User-Agent, spaces out requests to avoid hammering the server, and respects terms of service and copyright. Errors are normal on the web, so each fetch should catch exceptions and record the failure instead of crashing the whole run. A common slip here: Scraping a site that forbids it in robots.txt or its terms of service. The debugging exercise below demonstrates it: Network errors are normal. Catching them per URL lets the scraper record the failure and continue with the other pages.',
          syntax: 'from concurrent.futures import ThreadPoolExecutor\ndef fetch(url):\n    return f\'Fetched {url}\'\nurls = [\'https://a.example\', \'https://b.example\']\nwith ThreadPoolExecutor(max_workers=4) as pool:\n    print(list(pool.map(fetch, urls)))',
          analogy: 'A concurrent scraper is like a team of couriers: each one picks up a different parcel (page) at the same time, and they all report back to the same desk.',
